/** On-disk side of device identity (multi-device F2): `.hub/device/key{,.pub}`,
 *  `.hub/device.yml`, synced `devices.yml`, local `.hub/allowed_signers`, and the
 *  `ledger device` operations + doctor health checks built on them.
 *
 *  Rules (docs/multi-device-spec.md §2.1, §6, §8):
 *   - the private key lives only in `.hub/device/` (0700 dir, 0600 files / owner-only ACL),
 *     is generated by ssh-keygen, never printed, never read into this process;
 *   - init never regenerates an existing key and never changes an existing device_id;
 *   - revocation is monotonic, the revoked key leaves allowed_signers FIRST (fail safe),
 *     a slot is never handed out again;
 *   - every file we parse from disk is size-capped, symlink-refused and schema-validated;
 *     `allowed_signers` (the local trust anchor) is also owner/mode-checked before every read;
 *   - every mutating operation (init / approve / revoke / add / adopt / re-key) runs under ONE
 *     lock (`.hub/device.lock`) and re-reads its inputs inside it, so approve racing revoke can
 *     never resurrect a revoked key.
 */

import { randomBytes, timingSafeEqual } from 'node:crypto';
import { constants } from 'node:fs';
import { copyFile, link, lstat, mkdir, open, readdir, rm, writeFile } from 'node:fs/promises';
import nodePath from 'node:path';
import { parse as parseYaml, stringify as stringifyYaml } from 'yaml';
import {
  DEVICES_MAX_ENTRIES,
  DevicesError,
  REVOKE_REASON_MAX,
  acceptDevicesChange,
  deviceFileSchema,
  labelSchema,
  parseAllowedSigners,
  parseDevicesYaml,
  planAddDevice,
  devicesInvariantProblem,
  safeOutput,
  renderAllowedSigners,
  renderDevicesYaml,
  type DeviceEntry,
  type DeviceFile,
  type DevicesFile,
  type Signer,
} from './devices.ts';
import { renameRetry } from './fsretry.ts';
import { assertPrivateFile, ensurePrivateDir, isOwnedByMe, isStatOwnedByMe, TrustError } from './platformTrust.ts';
import { isSingleLine } from './sanitize.ts';
import {
  DEVICE_ID_RE,
  SshKeygenError,
  generateKeyPair,
  parseEd25519Pub,
  publicKeyOf,
  resolveSshKeygen,
  type Ed25519Pub,
} from './sshkey.ts';

const MAX_SMALL_FILE = 64 * 1024;
export const DEVICE_STALE_DAYS = 30;

export interface DeviceLayout {
  root: string;
  hubDir: string;
  deviceDir: string;
  keyFile: string;
  pubFile: string;
  /** `.hub/device.yml` (local identity). */
  deviceYml: string;
  /** `devices.yml` at the ledger root (synced). */
  devicesYml: string;
  allowedSigners: string;
  /** Private scratch root for verify (`withPrivateTmp`). */
  tmpDir: string;
}

export function deviceLayout(ledgerDir: string): DeviceLayout {
  const hubDir = nodePath.join(ledgerDir, '.hub');
  const deviceDir = nodePath.join(hubDir, 'device');
  return {
    root: ledgerDir,
    hubDir,
    deviceDir,
    keyFile: nodePath.join(deviceDir, 'key'),
    pubFile: nodePath.join(deviceDir, 'key.pub'),
    deviceYml: nodePath.join(hubDir, 'device.yml'),
    devicesYml: nodePath.join(ledgerDir, 'devices.yml'),
    allowedSigners: nodePath.join(hubDir, 'allowed_signers'),
    tmpDir: nodePath.join(hubDir, 'tmp'),
  };
}

/* ---------------- small-file IO (symlink-refusing, capped, atomic) ---------------- */

/** `null` = absent. Refuses symlinks and non-regular files; caps the size. No O_NOFOLLOW
 *  here (I1: only platformTrust uses it, and win32 has none): lstat → open → fstat and require
 *  the same dev+ino, so a path swapped for a symlink between the two calls is refused. */
async function readSmall(path: string, max = MAX_SMALL_FILE): Promise<string | null> {
  const name = nodePath.basename(path);
  let before;
  try {
    before = await lstat(path, { bigint: true });
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
    throw err;
  }
  if (before.isSymbolicLink()) throw new DevicesError('UNSAFE_FILE', `${name} is a symlink — refusing`);
  if (!before.isFile()) throw new DevicesError('UNSAFE_FILE', `${name} is not a regular file`);
  let fh;
  try {
    fh = await open(path, 'r');
  } catch (err) {
    // removed between lstat and open (a lock released by its holder): absent, not an error
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
    throw err;
  }
  try {
    const st = await fh.stat({ bigint: true });
    if (!st.isFile() || st.dev !== before.dev || st.ino !== before.ino) {
      throw new DevicesError('UNSAFE_FILE', `${name} changed while being opened — refusing`);
    }
    if (st.size > BigInt(max)) throw new DevicesError('UNSAFE_FILE', `${name} is too large`);
    return await fh.readFile('utf8');
  } finally {
    await fh.close();
  }
}

/** tmp (exclusive create, 0600) in the same directory + rename. */
async function writeAtomic(path: string, data: string): Promise<void> {
  const tmp = nodePath.join(nodePath.dirname(path), `.${randomBytes(6).toString('hex')}.tmp`);
  try {
    await writeFile(tmp, data, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
    await renameRetry(tmp, path);
  } catch (err) {
    await rm(tmp, { force: true }).catch(() => undefined);
    throw err;
  }
}

async function ensureHubDir(l: DeviceLayout): Promise<void> {
  if (process.platform === 'win32') {
    await ensurePrivateDir(l.hubDir);
  } else {
    await mkdir(l.root, { recursive: true, mode: 0o700 });
    await mkdir(l.hubDir, { recursive: true, mode: 0o700 });
  }
}

async function ensureDirs(l: DeviceLayout): Promise<void> {
  await ensureHubDir(l);
  await ensurePrivateDir(l.deviceDir);
}

/* ---------------- one lock for every mutating device operation (DK-5) ---------------- */

const LOCK_WAIT_MS = 10_000;
/** Upper bound for a caller-supplied `waitMs` (a typo must not park a request for minutes). */
const LOCK_WAIT_MAX_MS = 60_000;
/** A lock whose holder process is gone is taken over after this; any lock older than
 *  `LOCK_ABANDONED_MS` is abandoned (operations take milliseconds; a recycled pid must not wedge us). */
const LOCK_DEAD_HOLDER_MS = 2_000;
const LOCK_ABANDONED_MS = 5 * 60_000;
/** The takeover critical section is two small file ops; a takeover mutex older than this belongs to a
 *  crashed process. */
const TAKEOVER_STALE_MS = 10_000;

function pidAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (err) {
    return (err as NodeJS.ErrnoException).code !== 'ESRCH';
  }
}

/** A takeover mutex (`device.lock.takeover`) left behind by a crashed process: removed only when
 *  it is old AND unchanged since we read it. Best effort: the residual race (two processes both
 *  judging the SAME crashed mutex stale) needs a crash plus exact timing and is documented, not hidden. */
async function clearStaleTakeover(path: string): Promise<void> {
  const seen = await readSmall(path, 256);
  if (seen === null) return;
  const st = await lstat(path).catch(() => null);
  if (st === null || Math.abs(Date.now() - st.mtimeMs) <= TAKEOVER_STALE_MS) return;
  if ((await readSmall(path, 256)) === seen) await rm(path, { force: true });
}

/** `true` when a stale lock was removed (or vanished). `false` = not stale / someone else is taking
 *  it over: the caller waits and retries. Symlink / non-regular lock files throw (refused).
 *
 *  AL-16: the decision to remove is made on a read of the lock file; between that read and `rm`
 *  another process could have removed the stale lock AND created a fresh one, which a plain `rm`
 *  would then delete (two holders). So the re-read + compare + `rm` run under a second exclusive
 *  file (`device.lock.takeover`): inside it nobody else can remove or replace-after-remove, and the
 *  compare against the content we judged stale proves it is still that same instance. */
async function clearStaleLock(lockPath: string): Promise<boolean> {
  const first = await readSmall(lockPath, 256);
  if (first === null) return true; // vanished meanwhile: just retry the create
  const st = await lstat(lockPath).catch(() => null);
  if (st === null) return true;
  const age = Math.abs(Date.now() - st.mtimeMs); // clock jumps: distance, not difference
  const pid = /^(\d{1,10}) /.exec(first)?.[1];
  const dead = pid === undefined || !pidAlive(Number(pid));
  if (!((dead && age > LOCK_DEAD_HOLDER_MS) || age > LOCK_ABANDONED_MS)) return false;

  const takeoverPath = `${lockPath}.takeover`;
  const mine = `${String(process.pid)} ${String(Date.now())} ${randomBytes(8).toString('hex')}\n`;
  try {
    await writeFile(takeoverPath, mine, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code !== 'EEXIST') throw err;
    await clearStaleTakeover(takeoverPath);
    return false; // another process is mid-takeover: wait, then re-evaluate from scratch
  }
  try {
    if ((await readSmall(lockPath, 256)) !== first) return false; // replaced or released: not the stale instance any more
    await rm(lockPath, { force: true });
    return true;
  } finally {
    if ((await readSmall(takeoverPath, 256).catch(() => null)) === mine) await rm(takeoverPath, { force: true }).catch(() => undefined);
  }
}

export interface DeviceLockOptions {
  /** How long to wait for a live holder before `LOCKED` (ms, 0..60000; default 10000). Measured
   *  on a monotonic clock. `0` = one attempt (plus a stale takeover) and no waiting. */
  waitMs?: number;
}

/** Exclusive (`wx`, 0600) lock file next to the device identity. Re-entrancy is NOT supported:
 *  inner helpers take no lock; only the public operations do (a nested call waits for itself until
 *  `LOCKED`). Fails with `DevicesError('LOCKED')` after `waitMs`. */
async function lockLayout<T>(l: DeviceLayout, fn: () => Promise<T>, waitMs: number = LOCK_WAIT_MS): Promise<T> {
  await ensureHubDir(l);
  const lockPath = nodePath.join(l.hubDir, 'device.lock');
  const token = `${String(process.pid)} ${String(Date.now())} ${randomBytes(8).toString('hex')}\n`;
  const t0 = process.hrtime.bigint(); // monotonic: the wait budget must not follow the wall clock
  for (;;) {
    try {
      await writeFile(lockPath, token, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
      break;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== 'EEXIST') throw err;
    }
    if (await clearStaleLock(lockPath)) continue;
    if (Number(process.hrtime.bigint() - t0) / 1e6 > waitMs) {
      throw new DevicesError('LOCKED', 'another ledger device operation is running — retry in a moment');
    }
    await new Promise((r) => setTimeout(r, 15 + Math.floor(Math.random() * 25)));
  }
  try {
    return await fn();
  } finally {
    // Remove only OUR lock (a takeover after a very long stall must not delete the new holder's).
    if ((await readSmall(lockPath, 256).catch(() => null)) === token) await rm(lockPath, { force: true }).catch(() => undefined);
  }
}

/** The ledger-wide device lock (`.hub/device.lock`, cross-process) for callers outside this module
 *  (the sync APPLY critical section: clean check + read-tree + update-ref + prune). Lock order:
 *  innermost, short (lock order SF -> R -> Q -> D, docs/f3b-b3-plan.md §3). Not re-entrant. */
export async function withDeviceLock<T>(ledgerDir: string, fn: () => Promise<T>, opts: DeviceLockOptions = {}): Promise<T> {
  const w = opts.waitMs;
  const waitMs = typeof w === 'number' && Number.isFinite(w) ? Math.min(Math.max(w, 0), LOCK_WAIT_MAX_MS) : LOCK_WAIT_MS;
  return lockLayout(deviceLayout(ledgerDir), fn, waitMs);
}

/* ---------------- readers ---------------- */

export async function readDeviceFile(l: DeviceLayout): Promise<DeviceFile | null> {
  const text = await readSmall(l.deviceYml);
  if (text === null) return null;
  let raw: unknown;
  try {
    raw = parseYaml(text, { maxAliasCount: 0 });
  } catch {
    raw = null;
  }
  const res = deviceFileSchema.safeParse(raw);
  if (!res.success) {
    throw new DevicesError('DEVICE_INVALID', '.hub/device.yml is invalid — refusing (it is never regenerated automatically)');
  }
  return res.data;
}

async function writeDeviceFile(l: DeviceLayout, d: DeviceFile): Promise<void> {
  await writeAtomic(l.deviceYml, stringifyYaml(deviceFileSchema.parse(d), { lineWidth: 0 }));
}

export async function readDevices(l: DeviceLayout): Promise<DevicesFile | null> {
  const text = await readSmall(l.devicesYml);
  return text === null ? null : parseDevicesYaml(text);
}

/** `.hub/allowed_signers` is the local trust anchor: owner / mode / link-count are verified
 *  BEFORE every read (a group-writable or foreign-owned file is refused, never parsed). */
export async function readSigners(l: DeviceLayout): Promise<Signer[]> {
  if (!(await exists(l.allowedSigners))) return [];
  await assertPrivateFile(l.allowedSigners, { secret: true });
  const text = await readSmall(l.allowedSigners);
  return text === null ? [] : parseAllowedSigners(text);
}

async function readLocalPub(l: DeviceLayout): Promise<Ed25519Pub | null> {
  const text = await readSmall(l.pubFile, 1024);
  if (text === null) return null;
  const pub = parseEd25519Pub(text, { allowComment: true });
  if (pub === null) throw new DevicesError('KEY_INVALID', '.hub/device/key.pub is not an ed25519 public key');
  return pub;
}

/* ---------------- device init ---------------- */

export interface InitOptions {
  label?: string;
  /** Register this device as the TOFU root in devices.yml (refused if one exists). */
  root?: boolean;
  /** One-time migration of an F1 random device id to the key-derived one, only together with
   *  `root` and only while no devices.yml exists (DK-7). `ledger sync init` passes it; the plain
   *  `device init --root` does not. */
  rekeyLegacy?: boolean;
  /** Test seam. */
  bin?: string;
  now?: Date;
}

export interface InitResult {
  deviceId: string;
  label: string;
  slot: string;
  fingerprint: string;
  keyCreated: boolean;
  deviceYmlCreated: boolean;
  registeredRoot: boolean;
  inDevicesYml: boolean;
}

function defaultLabel(): string {
  return process.platform === 'darwin' ? 'mac' : process.platform === 'win32' ? 'win' : 'linux';
}

/** Exclusive publish of the freshly generated private key: `link` fails with EEXIST
 *  when a racing init won; filesystems without hard links fall back to an exclusive copy. */
async function publishKey(src: string, dest: string): Promise<boolean> {
  try {
    await link(src, dest);
    return true;
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === 'EEXIST') return false;
    try {
      await copyFile(src, dest, constants.COPYFILE_EXCL);
      return true;
    } catch (err2) {
      if ((err2 as NodeJS.ErrnoException).code === 'EEXIST') return false;
      throw err2;
    }
  }
}

async function exists(path: string): Promise<boolean> {
  try {
    await lstat(path);
    return true;
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return false;
    throw err;
  }
}

/** `.gen-*` scratch dirs older than this are leftovers of a crashed init (DK-6). */
const GEN_STALE_MS = 10 * 60_000;

async function sweepStaleGen(l: DeviceLayout, nowMs: number): Promise<void> {
  let names: string[];
  try {
    names = await readdir(l.deviceDir);
  } catch {
    return;
  }
  for (const name of names) {
    if (!/^\.gen-[0-9a-f]{12}$/.test(name)) continue;
    const p = nodePath.join(l.deviceDir, name);
    const st = await lstat(p).catch(() => null);
    // Only real directories we own; a symlink or foreign entry is left alone (never followed).
    if (st === null || st.isSymbolicLink() || !st.isDirectory()) continue;
    // win32: the owner is an SID, so ask the path (isStatOwnedByMe is fail-closed false there).
    if (!(process.platform === 'win32' ? await isOwnedByMe(p) : isStatOwnedByMe(st))) continue;
    if (Math.abs(nowMs - st.mtimeMs) <= GEN_STALE_MS) continue; // fresh: a live init may own it
    await rm(p, { recursive: true, force: true }).catch(() => undefined);
  }
}

/** Idempotent. Never regenerates a key, never rewrites an existing device_id (except the
 *  explicit one-time `rekeyLegacy` migration). */
export async function initDevice(ledgerDir: string, opts: InitOptions = {}): Promise<InitResult> {
  if (opts.label !== undefined && !labelSchema.safeParse(opts.label).success) {
    throw new DevicesError('LABEL_INVALID', 'label: lowercase letters, digits, - (max 32)');
  }
  if (opts.rekeyLegacy === true && opts.root !== true) {
    throw new DevicesError('REKEY_REFUSED', 'rekeyLegacy is only valid together with root');
  }
  const bin = opts.bin ?? (await resolveSshKeygen()); // fail closed before anything is created
  const l = deviceLayout(ledgerDir);
  await readDeviceFile(l); // a broken identity is refused before anything is created
  await ensureDirs(l);
  return lockLayout(l, () => initLocked(l, opts, bin));
}

async function initLocked(l: DeviceLayout, opts: InitOptions, bin: string): Promise<InitResult> {
  const existing = await readDeviceFile(l); // re-read under the lock
  await sweepStaleGen(l, (opts.now ?? new Date()).getTime());

  /* ---- key ---- */
  let keyCreated = false;
  let pub: Ed25519Pub;
  const hasKey = await exists(l.keyFile);
  if (hasKey) {
    await assertPrivateFile(l.keyFile, { secret: true });
    const onDisk = await readLocalPub(l);
    pub = onDisk ?? (await publicKeyOf(l.keyFile, bin));
    if (onDisk === null) await writeAtomic(l.pubFile, `${pub.line}\n`);
    else if ((await publicKeyOf(l.keyFile, bin)).line !== pub.line) {
      throw new DevicesError('KEY_MISMATCH', 'key.pub does not belong to the private key — refusing');
    }
  } else {
    if (await exists(l.pubFile)) {
      throw new DevicesError('KEY_INVALID', 'key.pub exists but the private key is missing — refusing to generate a new identity');
    }
    const gen = nodePath.join(l.deviceDir, `.gen-${randomBytes(6).toString('hex')}`);
    await ensurePrivateDir(gen);
    try {
      const genKey = nodePath.join(gen, 'key');
      await generateKeyPair(genKey, bin);
      const fresh = parseEd25519Pub((await readSmall(`${genKey}.pub`, 1024)) ?? '', { allowComment: true });
      if (fresh === null) throw new SshKeygenError('INVALID', 'ssh-keygen produced no usable public key');
      keyCreated = await publishKey(genKey, l.keyFile);
      if (keyCreated) {
        pub = fresh;
        await writeAtomic(l.pubFile, `${fresh.line}\n`);
      } else {
        // A racing init published first: adopt its key, never overwrite it.
        const theirs = await readLocalPub(l);
        pub = theirs ?? (await publicKeyOf(l.keyFile, bin));
        if (theirs === null) await writeAtomic(l.pubFile, `${pub.line}\n`);
      }
    } finally {
      await rm(gen, { recursive: true, force: true }).catch(() => undefined);
    }
    await assertPrivateFile(l.keyFile, { secret: true });
  }

  /* ---- device.yml: id is kept; fingerprint recorded ---- */
  let identity: DeviceFile;
  let deviceYmlCreated = false;
  if (existing === null) {
    identity = { device_id: pub.deviceId, label: opts.label ?? defaultLabel(), slot: '', key_fp: pub.fingerprint };
    await writeDeviceFile(l, identity);
    deviceYmlCreated = true;
  } else {
    if (existing.key_fp !== undefined && existing.key_fp !== pub.fingerprint) {
      throw new DevicesError('KEY_MISMATCH', 'device.yml records a different key fingerprint — refusing to touch it');
    }
    identity = existing;
    const labelChange = opts.label !== undefined && opts.label !== existing.label;
    if (labelChange && existing.key_fp !== undefined) {
      throw new DevicesError('LABEL_LOCKED', 'device is already initialised; its label is part of its registration');
    }
    if (existing.key_fp === undefined || labelChange) {
      identity = { ...existing, label: opts.label ?? existing.label, key_fp: pub.fingerprint };
      await writeDeviceFile(l, identity);
    }
  }

  /* ---- optional TOFU root ---- */
  let registeredRoot = false;
  let devices = await readDevices(l);
  if (opts.root === true) {
    const mine = devices?.devices.find((d) => d.id === identity.device_id);
    if (devices !== null) {
      if (mine === undefined || mine.pubkey !== pub.line || mine.slot !== '') {
        throw new DevicesError('ROOT_EXISTS', 'devices.yml already exists and is not this device\'s root entry — refusing');
      }
      // DK-7: a revoked root is never re-trusted by re-running init (that would undo the revocation locally).
      if (mine.revoked !== null) {
        throw new DevicesError('ROOT_REVOKED', 'this device\'s root entry in devices.yml is revoked — a revoked key is never trusted again');
      }
      await mergeSigner(l, { id: identity.device_id, pubkey: pub.line }); // idempotent
    } else {
      if (identity.slot !== '') throw new DevicesError('ROOT_SLOT', 'only the primary (slot "") can be the TOFU root');
      if (identity.device_id !== pub.deviceId) {
        // DK-7: the root id must be sha256(pubkey). A legacy random id is migrated only on request.
        if (opts.rekeyLegacy !== true) {
          throw new DevicesError('LEGACY_ID', 'this device still has a legacy random id — it must be re-keyed before it can be the root (ledger sync init does that)');
        }
        identity = await rekeyLocked(l, pub);
      }
      const entry: DeviceEntry = {
        id: identity.device_id,
        label: identity.label,
        slot: '',
        pubkey: pub.line,
        added: (opts.now ?? new Date()).toISOString(),
        added_by: identity.device_id,
        revoked: null,
        role: 'owner',
      };
      const file: DevicesFile = { devices: [entry] };
      const verdict = acceptDevicesChange(null, file, pub.line, new Set(), { allowRoot: true });
      if (!verdict.ok) throw new DevicesError('ROOT_INVALID', `root registration refused: ${verdict.reason}`);
      // Trust first, record second: a crash in between leaves only a self-trusted key.
      await mergeSigner(l, { id: entry.id, pubkey: pub.line });
      await writeAtomic(l.devicesYml, renderDevicesYaml(file));
      devices = file;
      registeredRoot = true;
    }
  }

  return {
    deviceId: identity.device_id,
    label: identity.label,
    slot: identity.slot,
    fingerprint: pub.fingerprint,
    keyCreated,
    deviceYmlCreated,
    registeredRoot,
    inDevicesYml: devices?.devices.some((d) => d.id === identity.device_id && d.pubkey === pub.line) ?? false,
  };
}

/* ---------------- legacy id re-key (DK-7) ---------------- */

/** Re-key `identity.device_id` (F1 random id) to the key-derived id. Caller holds the lock and
 *  has verified `pub` belongs to the private key. Crash-safe order: counters copied under the new
 *  name (exclusive), then device.yml, then the old counters file removed — ids can never move
 *  backwards because readers take the per-key max over every counters file. The hub caches the
 *  device identity in memory: run this only while no hub is writing to this ledger. */
async function rekeyLocked(l: DeviceLayout, pub: Ed25519Pub): Promise<DeviceFile> {
  const self = await readDeviceFile(l);
  if (self === null) throw new DevicesError('NOT_INITIALISED', 'no device identity to re-key (ledger device init)');
  if (self.device_id === pub.deviceId) return self;
  if (self.slot !== '') throw new DevicesError('REKEY_REFUSED', 'only the primary (slot "") has a legacy id');
  if ((await readDevices(l)) !== null) {
    throw new DevicesError('REKEY_REFUSED', 'devices.yml exists — an id that may be registered is never changed');
  }
  const oldFile = nodePath.join(l.root, 'counters', `${self.device_id}.yml`);
  const newFile = nodePath.join(l.root, 'counters', `${pub.deviceId}.yml`);
  const oldText = await readSmall(oldFile);
  if (oldText !== null) {
    const tmp = nodePath.join(nodePath.dirname(newFile), `.${randomBytes(6).toString('hex')}.tmp`);
    await writeFile(tmp, oldText, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
    try {
      const published = await publishKey(tmp, newFile); // exclusive: false = a file already exists
      if (!published && (await readSmall(newFile)) !== oldText) {
        throw new DevicesError('REKEY_CONFLICT', `counters/${pub.deviceId}.yml already exists with different content — refusing`);
      }
    } finally {
      await rm(tmp, { force: true }).catch(() => undefined);
    }
  }
  const identity: DeviceFile = { ...self, device_id: pub.deviceId, key_fp: pub.fingerprint };
  await writeDeviceFile(l, identity);
  if (oldText !== null) await rm(oldFile, { force: true }).catch(() => undefined);
  return identity;
}

/** Public form for `ledger sync init`: validates the key like `device init`, then re-keys.
 *  Returns `null` when the id is already key-derived. Never touches a registered device. */
export async function rekeyLegacyDeviceId(
  ledgerDir: string,
  opts: { bin?: string } = {},
): Promise<{ from: string; to: string } | null> {
  const bin = opts.bin ?? (await resolveSshKeygen());
  const l = deviceLayout(ledgerDir);
  return lockLayout(l, async () => {
    const self = await readDeviceFile(l);
    if (self === null) throw new DevicesError('NOT_INITIALISED', 'no device identity to re-key (ledger device init)');
    await assertPrivateFile(l.keyFile, { secret: true });
    const onDisk = await readLocalPub(l);
    const pub = await publicKeyOf(l.keyFile, bin);
    if (onDisk === null || onDisk.line !== pub.line) {
      throw new DevicesError('KEY_MISMATCH', 'key.pub does not belong to the private key — refusing');
    }
    if (self.key_fp !== undefined && self.key_fp !== pub.fingerprint) {
      throw new DevicesError('KEY_MISMATCH', 'device.yml records a different key fingerprint — refusing to touch it');
    }
    if (self.device_id === pub.deviceId) return null;
    const after = await rekeyLocked(l, pub);
    return { from: self.device_id, to: after.device_id };
  });
}

/** Add one signer; the same principal with a DIFFERENT key is a conflict, never a silent replace. */
async function mergeSigner(l: DeviceLayout, s: Signer): Promise<boolean> {
  const signers = await readSigners(l);
  const have = signers.find((x) => x.id === s.id);
  if (have !== undefined) {
    if (have.pubkey !== s.pubkey) throw new DevicesError('SIGNER_CONFLICT', `${s.id} is already trusted with a different key`);
    return false;
  }
  await writeAtomic(l.allowedSigners, renderAllowedSigners([...signers, s]));
  return true;
}

/* ---------------- list / approve / revoke ---------------- */

export interface DeviceRow {
  id: string;
  label: string;
  slot: string;
  fingerprint: string;
  status: 'active' | 'revoked';
  trusted: boolean;
  self: boolean;
  lastSeen: string | null;
}

export async function listDevices(ledgerDir: string): Promise<DeviceRow[]> {
  const l = deviceLayout(ledgerDir);
  const devices = await readDevices(l);
  if (devices === null) return [];
  const signers = new Set((await readSigners(l)).map((s) => `${s.id} ${s.pubkey}`));
  const self = await readDeviceFile(l);
  return devices.devices.map((d) => ({
    id: d.id,
    label: d.label,
    slot: d.slot,
    fingerprint: parseEd25519Pub(d.pubkey)?.fingerprint ?? '?',
    status: d.revoked === null ? 'active' : 'revoked',
    trusted: d.revoked === null && signers.has(`${d.id} ${d.pubkey}`),
    self: self?.device_id === d.id,
    lastSeen: d.last_seen ?? null,
  }));
}

function requireId(id: string): void {
  if (!DEVICE_ID_RE.test(id)) throw new DevicesError('ID_INVALID', 'device id must look like d_xxxxxxxxxx (a-z, 2-7)');
}

/** The acting device must itself be a registered, non-revoked member whose local key matches. */
async function requireMember(l: DeviceLayout): Promise<{ self: DeviceFile; devices: DevicesFile; pub: Ed25519Pub }> {
  const self = await readDeviceFile(l);
  const devices = await readDevices(l);
  const pub = await readLocalPub(l);
  const mine = devices?.devices.find((d) => d.id === self?.device_id);
  if (self === null || devices === null || pub === null || mine === undefined || mine.pubkey !== pub.line) {
    throw new DevicesError('NOT_MEMBER', 'this device is not registered in devices.yml (ledger device init --root on the first device)');
  }
  if (mine.revoked !== null) throw new DevicesError('NOT_MEMBER', 'this device is revoked');
  return { self, devices, pub };
}

const FP_RE = /^SHA256:[A-Za-z0-9+/]{43}$/;

/** The human-verified fingerprint (what the other device printed) must equal the key's. */
function requireFingerprint(given: unknown, actual: string): void {
  if (typeof given !== 'string' || given === '') {
    throw new DevicesError('FP_REQUIRED', 'the key fingerprint is required (SHA256:…) — compare it with what the other device prints');
  }
  const a = Buffer.from(given);
  const b = Buffer.from(actual);
  if (!FP_RE.test(given) || a.length !== b.length || !timingSafeEqual(a, b)) {
    throw new DevicesError('FP_MISMATCH', 'fingerprint does not match that device\'s key — refusing');
  }
}

/** Approve = trust that device's key locally (`.hub/allowed_signers`). `fingerprint` is the
 *  `SHA256:…` the human read off the other device; it must match the registered key (DK-1). */
export async function approveDevice(ledgerDir: string, id: string, fingerprint: string): Promise<{ added: boolean }> {
  requireId(id);
  const l = deviceLayout(ledgerDir);
  return lockLayout(l, () => approveLockedL(l, id, fingerprint));
}

async function approveLockedL(l: DeviceLayout, id: string, fingerprint: string): Promise<{ added: boolean }> {
  const { devices } = await requireMember(l);
  const target = devices.devices.find((d) => d.id === id);
  if (target === undefined) throw new DevicesError('NOT_FOUND', `${id} is not in devices.yml`);
  if (target.revoked !== null) throw new DevicesError('REVOKED', `${id} is revoked — a revoked key is never trusted again`);
  const pub = parseEd25519Pub(target.pubkey);
  if (pub === null) throw new DevicesError('KEY_INVALID', `${id}: registered key is invalid`);
  requireFingerprint(fingerprint, pub.fingerprint);
  return { added: await mergeSigner(l, { id, pubkey: pub.line }) };
}

/** `approveDevice` for a caller that ALREADY holds the device lock (`withDeviceLock`, not re-entrant:
 *  calling `approveDevice` there would deadlock). Same checks: member, registered, not revoked, fp equal. */
export async function approveLocked(ledgerDir: string, id: string, fingerprint: string): Promise<{ added: boolean }> {
  requireId(id);
  return approveLockedL(deviceLayout(ledgerDir), id, fingerprint);
}

/** JOIN bootstrap (OQ-5 = A): trust every NON-revoked device of a registry the caller already validated
 *  (`validateGenesis`), anchored on the root fingerprint the HUMAN confirmed out of band. Only on a
 *  device that trusts nobody yet (`allowed_signers` absent or empty): this can never widen an existing
 *  trust set. The root entry (slot "", self-added) must have exactly `rootFp` (`timingSafeEqual`); a
 *  revoked key (the root included) is never added. Takes the device lock itself (the joiner holds none). */
export async function bootstrapSigners(
  ledgerDir: string,
  devices: DevicesFile,
  rootFp: string,
): Promise<{ added: string[] }> {
  if (typeof rootFp !== 'string' || !FP_RE.test(rootFp)) {
    throw new DevicesError('FP_REQUIRED', 'the root key fingerprint is required (SHA256:…)');
  }
  const problem = devicesInvariantProblem(devices);
  if (problem !== null || devices.devices.length > DEVICES_MAX_ENTRIES) {
    throw new DevicesError('DEVICES_INVALID', 'devices registry is invalid');
  }
  const root = devices.devices.find((d) => d.slot === '' && d.added_by === d.id);
  const rootPub = root === undefined ? null : parseEd25519Pub(root.pubkey);
  if (root === undefined || rootPub === null) throw new DevicesError('NO_ROOT', 'the registry has no root device');
  const want = Buffer.from(rootFp);
  const have = Buffer.from(rootPub.fingerprint);
  if (want.length !== have.length || !timingSafeEqual(want, have)) {
    throw new DevicesError('FP_MISMATCH', 'root key fingerprint does not match — refusing');
  }
  const l = deviceLayout(ledgerDir);
  return lockLayout(l, async () => {
    await ensureHubDir(l);
    if ((await readSigners(l)).length !== 0) {
      throw new DevicesError('SIGNERS_NOT_EMPTY', 'this device already trusts signers — bootstrap refused');
    }
    const signers: Signer[] = [];
    for (const d of devices.devices) {
      if (d.revoked !== null) continue;
      const pub = parseEd25519Pub(d.pubkey);
      if (pub === null) throw new DevicesError('KEY_INVALID', `${d.id}: registered key is invalid`);
      signers.push({ id: d.id, pubkey: pub.line });
    }
    await writeAtomic(l.allowedSigners, renderAllowedSigners(signers));
    return { added: signers.map((x) => x.id).sort() };
  });
}

/** Monotonic. The key leaves allowed_signers first (fail safe), then the record is written. */
export async function revokeDevice(
  ledgerDir: string,
  id: string,
  reason: string,
  now: Date = new Date(),
): Promise<void> {
  requireId(id);
  const why = reason.trim();
  if (why === '' || why.length > REVOKE_REASON_MAX || !isSingleLine(why)) {
    throw new DevicesError('REASON_INVALID', `--reason is required: one line, max ${REVOKE_REASON_MAX} chars`);
  }
  const l = deviceLayout(ledgerDir);
  await lockLayout(l, async () => {
    const { self, devices } = await requireMember(l);
    if (id === self.device_id) throw new DevicesError('SELF_REVOKE', 'refusing to revoke this device itself — revoke it from another device');
    const target = devices.devices.find((d) => d.id === id);
    if (target === undefined) throw new DevicesError('NOT_FOUND', `${id} is not in devices.yml`);
    if (target.revoked !== null) throw new DevicesError('REVOKED', `${id} is already revoked (revocation is permanent)`);
    const signers = await readSigners(l);
    await writeAtomic(l.allowedSigners, renderAllowedSigners(signers.filter((s) => s.id !== id)));
    const next: DevicesFile = {
      devices: devices.devices.map((d) =>
        d.id === id ? { ...d, revoked: { at: now.toISOString(), by: self.device_id, reason: why } } : d,
      ),
    };
    await writeAtomic(l.devicesYml, renderDevicesYaml(next));
  });
}

/** Drop every `allowed_signers` entry whose key (or id) is REVOKED in `devices.yml` (the
 *  worktree copy = main after APPLY, T-B3-8). ONLY removes, never adds or rewrites a key, so it can
 *  never widen trust. The CALLER holds `withDeviceLock` (this takes no lock: the lock is not
 *  re-entrant). A missing `devices.yml` / `allowed_signers` removes nothing; an invalid one throws
 *  (fail closed: the caller halts, nothing is guessed). Returns the removed ids (sorted). */
export async function pruneRevokedSigners(ledgerDir: string): Promise<{ removed: string[] }> {
  const l = deviceLayout(ledgerDir);
  const devices = await readDevices(l);
  if (devices === null) return { removed: [] };
  const revoked = devices.devices.filter((d) => d.revoked !== null);
  if (revoked.length === 0) return { removed: [] };
  const revokedIds = new Set(revoked.map((d) => d.id));
  const revokedKeys = new Set(revoked.map((d) => parseEd25519Pub(d.pubkey)?.line ?? d.pubkey));
  const signers = await readSigners(l);
  const keep = signers.filter((s) => !revokedIds.has(s.id) && !revokedKeys.has(s.pubkey));
  if (keep.length === signers.length) return { removed: [] };
  await writeAtomic(l.allowedSigners, renderAllowedSigners(keep));
  const kept = new Set(keep.map((s) => s.id));
  return { removed: signers.filter((s) => !kept.has(s.id)).map((s) => s.id).sort() };
}

/* ---------------- enrolment primitives (OQ-1 = A) ---------------- */

export interface AddResult {
  id: string;
  label: string;
  slot: string;
  fingerprint: string;
}

/** TRUSTED side of enrolment: register a joining device. The joiner printed its canonical public
 *  key line and fingerprint; the human compares the fingerprint and passes it as `fp` (the
 *  key is rejected unless they match). Entry: id derived from the key, lowest never-used slot
 *  (revoked slots stay retired), `added_by` = this device. Does NOT approve the key locally —
 *  approval is a separate, equally fingerprint-confirmed step (`approveDevice`). The result is
 *  self-checked with `acceptDevicesChange` exactly as a peer would check it. */
export async function addDevice(
  ledgerDir: string,
  pubkeyLine: string,
  label: string,
  fp: string,
  now: Date = new Date(),
): Promise<AddResult> {
  const pub = parseEd25519Pub(pubkeyLine);
  if (pub === null || pub.line !== pubkeyLine) {
    throw new DevicesError('KEY_INVALID', 'public key must be exactly `ssh-ed25519 <base64>` (no comment, no options)');
  }
  if (!labelSchema.safeParse(label).success) {
    throw new DevicesError('LABEL_INVALID', 'label: lowercase letters, digits, - (max 32)');
  }
  requireFingerprint(fp, pub.fingerprint);
  const l = deviceLayout(ledgerDir);
  return lockLayout(l, async () => {
    const { self, devices, pub: mine } = await requireMember(l);
    const { next, entry } = planAddDevice(devices, self.device_id, pub, label, now.getTime());
    const trusted = new Set((await readSigners(l)).map((s) => s.pubkey));
    const verdict = acceptDevicesChange(devices, next, mine.line, trusted, { commitTimeMs: now.getTime() });
    if (!verdict.ok) throw new DevicesError('ADD_REFUSED', `device add refused: ${verdict.reason}`);
    await writeAtomic(l.devicesYml, renderDevicesYaml(next));
    return { id: entry.id, label, slot: entry.slot, fingerprint: pub.fingerprint };
  });
}

/** JOINER side: after a trusted device registered this device's key (and devices.yml arrived),
 *  take over the registered label and slot in `.hub/device.yml`. Refused unless the registry
 *  entry is this device's own key AND id, is not revoked, and this device has not minted ids
 *  yet (a counters file would mean ids under the old slot that may collide). Idempotent. */
export async function adoptSlot(
  ledgerDir: string,
  opts: { bin?: string } = {},
): Promise<{ id: string; label: string; slot: string; changed: boolean }> {
  const bin = opts.bin ?? (await resolveSshKeygen());
  const l = deviceLayout(ledgerDir);
  return lockLayout(l, async () => {
    const self = await readDeviceFile(l);
    const pub = await readLocalPub(l);
    if (self === null || pub === null) throw new DevicesError('NOT_INITIALISED', 'no device identity yet (ledger device init)');
    await assertPrivateFile(l.keyFile, { secret: true });
    if ((await publicKeyOf(l.keyFile, bin)).line !== pub.line) {
      throw new DevicesError('KEY_MISMATCH', 'key.pub does not belong to the private key — refusing');
    }
    const devices = await readDevices(l);
    if (devices === null) throw new DevicesError('NOT_FOUND', 'devices.yml is not here yet — sync first');
    const entry = devices.devices.find((d) => d.pubkey === pub.line);
    if (entry === undefined) {
      throw new DevicesError('NOT_REGISTERED', 'this device\'s key is not in devices.yml — a trusted device must run `ledger device add` first');
    }
    if (entry.id !== self.device_id) {
      throw new DevicesError('ID_MISMATCH', 'device.yml id is not the id registered for this key (legacy random id) — re-key it first');
    }
    if (entry.revoked !== null) throw new DevicesError('REVOKED', 'this device is revoked');
    if (self.slot === entry.slot && self.label === entry.label && self.key_fp === pub.fingerprint) {
      return { id: entry.id, label: entry.label, slot: entry.slot, changed: false };
    }
    if (self.slot !== '' && self.slot !== entry.slot) {
      throw new DevicesError('SLOT_CONFLICT', 'device.yml already holds a different slot — refusing to change it');
    }
    if (self.slot !== entry.slot && (await exists(nodePath.join(l.root, 'counters', `${self.device_id}.yml`)))) {
      throw new DevicesError('ADOPT_USED', 'this device already minted ids under its old slot — refusing to switch slot');
    }
    await writeDeviceFile(l, { ...self, label: entry.label, slot: entry.slot, key_fp: pub.fingerprint });
    return { id: entry.id, label: entry.label, slot: entry.slot, changed: true };
  });
}

/* ---------------- doctor ---------------- */

export interface DeviceCheck {
  id: string;
  status: 'ok' | 'warn' | 'fail' | 'info';
  detail: string;
}

/** Checks only appear once device identity exists (a plain local ledger prints nothing new).
 *  Every detail line is passed through `safeOutput` (DK-2): some of it derives from files a peer
 *  can write, and it ends up on a terminal. */
export async function deviceHealth(ledgerDir: string, nowMs: number = Date.now()): Promise<DeviceCheck[]> {
  const checks = await deviceHealthRaw(ledgerDir, nowMs);
  return checks.map((c) => ({ ...c, detail: safeOutput(c.detail, 400) }));
}

async function deviceHealthRaw(ledgerDir: string, nowMs: number): Promise<DeviceCheck[]> {
  const l = deviceLayout(ledgerDir);
  const out: DeviceCheck[] = [];
  const keyExists = await exists(l.keyFile).catch(() => false);
  const devicesExists = await exists(l.devicesYml).catch(() => false);
  if (!keyExists && !devicesExists && !(await exists(l.allowedSigners).catch(() => false))) return out;

  let devices: DevicesFile | null = null;
  try {
    devices = await readDevices(l);
  } catch (err) {
    out.push({ id: 'device_key', status: 'fail', detail: `device key: ${err instanceof Error ? err.message : 'devices.yml unreadable'}` });
    return out;
  }

  /* ---- device_key ---- */
  const problems: string[] = [];
  let note = 'present, private';
  let self: DeviceFile | null = null;
  try {
    self = await readDeviceFile(l);
  } catch (err) {
    problems.push((err as Error).message);
  }
  let pub: Ed25519Pub | null = null;
  if (!keyExists) {
    if (self !== null && devices?.devices.some((d) => d.id === self?.device_id)) {
      problems.push('private key is MISSING although this device is registered');
    }
  } else {
    try {
      await assertPrivateFile(l.keyFile, { secret: true });
    } catch (err) {
      problems.push(err instanceof TrustError ? `key file is not private (${err.code})` : 'key file cannot be inspected');
    }
    try {
      pub = await readLocalPub(l);
    } catch (err) {
      problems.push((err as Error).message);
    }
    if (pub === null && problems.length === 0) problems.push('key.pub is missing');
    if (pub !== null) {
      if (self?.key_fp !== undefined && self.key_fp !== pub.fingerprint) problems.push('device.yml fingerprint does not match key.pub');
      const mine = devices?.devices.find((d) => d.id === self?.device_id);
      if (devices !== null && mine === undefined) note = 'present, private, NOT registered in devices.yml';
      else if (mine !== undefined && mine.pubkey !== pub.line) problems.push('key.pub differs from this device\'s devices.yml entry');
      else if (mine?.revoked) problems.push('this device is REVOKED in devices.yml');
    }
  }
  if (keyExists || problems.length > 0) {
    out.push(
      problems.length > 0
        ? { id: 'device_key', status: 'fail', detail: `device key: ${problems.join('; ')}` }
        : { id: 'device_key', status: note.includes('NOT') ? 'warn' : 'ok', detail: `device key: ${note}${pub ? ` (${pub.fingerprint})` : ''}` },
    );
  }

  /* ---- device_signers ---- */
  try {
    const signers = await readSigners(l);
    if (signers.length > 0 || (await exists(l.allowedSigners))) {
      const bad: string[] = [];
      for (const s of signers) {
        const entry = devices?.devices.find((d) => d.id === s.id);
        if (entry === undefined) bad.push(`${s.id} not in devices.yml`);
        else if (entry.pubkey !== s.pubkey) bad.push(`${s.id} key differs from devices.yml`);
        else if (entry.revoked !== null) bad.push(`${s.id} is revoked but still trusted`);
      }
      out.push(
        bad.length > 0
          ? { id: 'device_signers', status: 'fail', detail: `allowed_signers: ${bad.join('; ')}` }
          : { id: 'device_signers', status: 'ok', detail: `allowed_signers: ${signers.length} trusted key(s)` },
      );
    }
  } catch (err) {
    const why = err instanceof DevicesError ? err.message : err instanceof TrustError ? `not private (${err.code})` : 'unreadable';
    out.push({ id: 'device_signers', status: 'fail', detail: `allowed_signers: ${why}` });
  }

  /* ---- devices_stale (only when last_seen is recorded) ---- */
  const stale: string[] = [];
  let seenAny = false;
  for (const d of devices?.devices ?? []) {
    if (d.revoked !== null || d.last_seen === undefined) continue;
    seenAny = true;
    // Math.abs: a clock that jumped (sleep/wake, NTP) must not make a device look "from the future".
    if (Math.abs(nowMs - Date.parse(d.last_seen)) > DEVICE_STALE_DAYS * 86_400_000) stale.push(d.id);
  }
  if (seenAny) {
    out.push(
      stale.length > 0
        ? { id: 'devices_stale', status: 'warn', detail: `devices unseen > ${DEVICE_STALE_DAYS} days: ${stale.slice(0, 5).join(', ')} — consider \`ledger device revoke <id> --reason …\`` }
        : { id: 'devices_stale', status: 'ok', detail: `devices seen within ${DEVICE_STALE_DAYS} days` },
    );
  }
  return out;
}
